  const kleinbetrag = !!g && beleg.beleg !== "gutschrift" && Number.isFinite(brutto) && brutto > 0 && brutto <= g.betrag
    && !["reverse_charge", "nicht_steuerbar"].includes(art);
  return { kleinbetrag, grenze: g?.betrag ?? null, norm: g?.norm ?? "" };
}

